## 1. Create `Services/ThemeService.cs`

```csharp
namespace sv_0d17b7b3dca74303a7fff2eb20aed41b.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}
```

## 2. Create `Components/Layout/ThemeIndicator.razor`

This is an **interactive island** embedded in the static layout. It subscribes to ThemeService changes.

```razor
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<span class="badge" style="background-color: @ThemeService.AccentColor; cursor: pointer;"
      title="Current theme" @onclick="CycleTheme">
    @ThemeIcon @ThemeService.Theme
</span>

@code {
    private string ThemeIcon => ThemeService.Theme switch
    {
        Services.ThemeMode.Light => "☀️",
        Services.ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void CycleTheme()
    {
        ThemeService.Theme = ThemeService.Theme switch
        {
            Services.ThemeMode.Light => Services.ThemeMode.Dark,
            Services.ThemeMode.Dark => Services.ThemeMode.System,
            _ => Services.ThemeMode.Light
        };
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}
```

