</style>

@code {
    private string BgColor => ThemeService.Theme switch
    {
        Services.ThemeMode.Dark => "#1a1a2e",
        Services.ThemeMode.Light => "#ffffff",
        _ => "#ffffff"  // System default; real impl would use JS to detect
    };

    private string TextColor => ThemeService.Theme switch
    {
        Services.ThemeMode.Dark => "#e0e0e0",
