 @page "/settings"
 @rendermode InteractiveServer
 @implements IDisposable
 @inject Services.ThemeService ThemeService

 <PageTitle>Settings</PageTitle>

 <h1>User Preferences</h1>

 <div class="card p-4" style="max-width: 500px;">
     <h4>Theme</h4>
     <div class="btn-group mb-3" role="group">
         @foreach (var mode in Enum.GetValues<Services.ThemeMode>())
         {
             <button class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-secondary")"
                     @onclick="() => ThemeService.Theme = mode">
                 @mode
             </button>
         }
     </div>

     <h4>Accent Color</h4>
     <div class="d-flex align-items-center gap-3 mb-3">
         <input type="color" class="form-control form-control-color"
                value="@ThemeService.AccentColor"
                @onchange="OnAccentColorChanged" />
         <span>@ThemeService.AccentColor</span>
     </div>

     <div class="mt-3 p-3 rounded" style="background-color: var(--app-accent-color); color: white;">
         Preview: This box uses your accent color.
     </div>
 </div>

 @code {
     protected override void OnInitialized()
     {
         ThemeService.OnChange += HandleThemeChanged;
     }

     private void OnAccentColorChanged(ChangeEventArgs e)
     {
         ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
     }

     private void HandleThemeChanged()
     {
         InvokeAsync(StateHasChanged);
     }

     public void Dispose()
     {
         ThemeService.OnChange -= HandleThemeChanged;
     }
 }

